<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {http,dataOf} from '../api/http'
import {stepUpHeader,withStepUp} from '../api/stepUp'
import {useAuthStore} from '../stores/auth'

type RoleKey='management'|'rnd'|'production'|'quality'
type DashboardCard={label:string;value:string;hint:string;source:string;route:string;tone:string}

const auth=useAuthStore(),router=useRouter(),data=ref<any>({}),report=ref<any>({}),loading=ref(true),exporting=ref(false)
const role=ref<RoleKey>('management'),configVisible=ref(false)
const enabled=ref({trend:true,status:true,exceptions:true,sources:true,platform:true})
const roles=[{key:'management',label:'管理层',caption:'全域经营与风险'},{key:'rnd',label:'研发',caption:'项目与实验'},{key:'production',label:'生产',caption:'工单与设备'},{key:'quality',label:'质量',caption:'检验与缺陷'}] as const

const roleContent:Record<RoleKey,{title:string;subtitle:string;cards:DashboardCard[];trendTitle:string;seriesA:string;seriesB:string;trend:number[];compare:number[];status:{label:string;value:number;color:string}[]}>= {
 management:{title:'企业数据综合驾驶舱',subtitle:'研发、生产、质量、设备与治理指标统一汇聚，面向管理决策快速下钻。',trendTitle:'跨域经营趋势',seriesA:'计划达成',seriesB:'质量稳定',trend:[72,76,74,81,84,87,86,91],compare:[82,79,84,86,87,89,92,94],cards:[
  {label:'在研项目',value:'12',hint:'2 项进入关键里程碑',source:'平台 · 研发',route:'/research/projects',tone:'cyan'},
  {label:'生产计划达成率',value:'86.4%',hint:'较上周 +4.2%',source:'MES',route:'/production/work-orders',tone:'blue'},
  {label:'一次检验合格率',value:'98.7%',hint:'质量红线内稳定',source:'平台 · 质量',route:'/quality/inspections',tone:'mint'},
  {label:'设备综合在线率',value:'96.2%',hint:'3 台设备待关注',source:'IoT / 设备',route:'/assets/devices',tone:'amber'}],status:[{label:'正常运行',value:76,color:'#36d9b0'},{label:'需要关注',value:16,color:'#f3b54a'},{label:'异常阻断',value:8,color:'#ff667d'}]},
 rnd:{title:'研发角色驾驶舱',subtitle:'围绕项目、实验、工艺验证与仿真任务配置研发工作组件。',trendTitle:'研发任务燃尽与实验通过率',seriesA:'任务完成',seriesB:'实验通过',trend:[38,46,55,59,66,72,78,86],compare:[62,68,65,72,75,82,86,91],cards:[
  {label:'活跃研发项目',value:'8',hint:'3 项本月验收',source:'平台 · 研发',route:'/research/projects',tone:'cyan'},
  {label:'进行中实验',value:'24',hint:'6 组等待结果',source:'实验管理',route:'/research/experiments',tone:'blue'},
  {label:'工艺窗口覆盖率',value:'82.5%',hint:'本周新增 4 组',source:'工艺实验',route:'/research/process-experiments',tone:'mint'},
  {label:'仿真任务队列',value:'6',hint:'2 个模型计算中',source:'仿真平台',route:'/research/simulations',tone:'amber'}],status:[{label:'按计划',value:68,color:'#36d9b0'},{label:'存在风险',value:23,color:'#f3b54a'},{label:'已经延期',value:9,color:'#ff667d'}]},
 production:{title:'生产角色驾驶舱',subtitle:'MES工单、批次进度、设备状态与实时参数形成一张生产态势图。',trendTitle:'产出与计划完成趋势',seriesA:'实际产出',seriesB:'计划产出',trend:[61,69,66,78,82,76,88,92],compare:[70,72,74,78,80,84,88,90],cards:[
  {label:'今日生产工单',value:'36',hint:'28 个正在执行',source:'MES',route:'/production/work-orders',tone:'cyan'},
  {label:'在制生产批次',value:'18',hint:'4 批次接近完工',source:'MES',route:'/production/batches',tone:'blue'},
  {label:'产线负载率',value:'84.6%',hint:'A02 产线负载最高',source:'MES / IoT',route:'/production/overview',tone:'mint'},
  {label:'设备实时告警',value:'3',hint:'1 项需立即处理',source:'IoT / 设备',route:'/production/realtime',tone:'amber'}],status:[{label:'运行',value:72,color:'#36d9b0'},{label:'待机',value:21,color:'#4b8dff'},{label:'告警',value:7,color:'#ff667d'}]},
 quality:{title:'质量角色驾驶舱',subtitle:'汇聚检验、CT/金相、硬度厚度、疲劳与缺陷数据，快速定位质量风险。',trendTitle:'合格率与缺陷闭环趋势',seriesA:'一次合格率',seriesB:'缺陷闭环率',trend:[91,92,94,93,96,97,96,99],compare:[72,76,81,84,82,88,91,95],cards:[
  {label:'待判定检验',value:'17',hint:'5 项今日到期',source:'平台 · 质量',route:'/quality/inspections',tone:'cyan'},
  {label:'CT / 金相任务',value:'9',hint:'2 个缺陷待标注',source:'检测设备',route:'/quality/ct-metallography',tone:'blue'},
  {label:'疲劳试验运行中',value:'6',hint:'最长已达 82 万次',source:'试验设备',route:'/quality/fatigue',tone:'mint'},
  {label:'高风险缺陷',value:'4',hint:'关联 3 个生产批次',source:'质量分析',route:'/quality/defects',tone:'amber'}],status:[{label:'合格',value:81,color:'#36d9b0'},{label:'待复核',value:13,color:'#f3b54a'},{label:'不合格',value:6,color:'#ff667d'}]}
}
const current=computed(()=>roleContent[role.value])
const exceptions=[
 {level:'紧急',title:'SLM-07 氧含量超过预警阈值',detail:'关联工单 WO-260813 · TA15 批次',source:'IoT',time:'2 分钟前',route:'/production/realtime'},
 {level:'高',title:'髋臼杯 AC-22 CT 孔隙缺陷待复核',detail:'检验记录 QC-260813-018',source:'质量平台',time:'18 分钟前',route:'/quality/ct-metallography'},
 {level:'中',title:'MES 工单同步出现 12 条字段映射异常',detail:'同步任务 MES-WO-INCR',source:'集成中心',time:'46 分钟前',route:'/integration/exceptions'},
 {level:'中',title:'多孔结构项目里程碑存在延期风险',detail:'项目 RND-2026-008',source:'研发平台',time:'1 小时前',route:'/research/projects'}
]
const sourceNodes=[{name:'MES',desc:'工单 · 批次 · 执行',state:'在线',tone:'cyan'},{name:'IoT',desc:'设备 · 参数 · 告警',state:'实时',tone:'mint'},{name:'研发平台',desc:'项目 · 实验 · 仿真',state:'已聚合',tone:'blue'},{name:'质量平台',desc:'检验 · 缺陷 · 报告',state:'已聚合',tone:'violet'},{name:'治理中心',desc:'主数据 · 质量规则',state:'受控',tone:'amber'}]
const platformCards=computed(()=>[
 ['完整模板',data.value.templateCount||0,'/templates'],['统一数据集',data.value.datasetCount||0,'/datasets'],['可信发布记录',data.value.publishedRecordCount||0,'/datasets'],['可见数据记录',data.value.recordCount||0,'/datasets']
])
onMounted(async()=>{try{const [overview,decision]=await Promise.all([http.get('/dashboard'),http.get('/dashboard/report')]);data.value=dataOf(overview);report.value=dataOf(decision)}finally{loading.value=false}})
async function exportReport(){exporting.value=true;try{const endpoint='/dashboard/report/export';const blob=await withStepUp({purpose:'EXPORT',method:'GET',target:endpoint,label:'导出当前权限范围的决策分析报表'},token=>http.get(endpoint,{responseType:'blob',headers:stepUpHeader(token)})) as unknown as Blob;const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download='decision-report.csv';anchor.click();URL.revokeObjectURL(url)}finally{exporting.value=false}}
function drill(route:string){router.push(route)}
</script>

<template><div class="page cockpit" v-loading="loading">
 <header class="cockpit-head"><div><p><i></i>ENTERPRISE DATA COMMAND</p><h1>{{current.title}}</h1><span>{{current.subtitle}}</span></div><div class="role-switch"><button v-for="item in roles" :key="item.key" :class="{active:role===item.key}" @click="role=item.key"><b>{{item.label}}</b><small>{{item.caption}}</small></button><button class="config" @click="configVisible=true">⚙<small>组件配置</small></button></div></header>

 <section class="source-ribbon"><b>聚合数据来源</b><span>MES · 生产执行</span><span>IoT · 设备实时状态</span><span>研发平台 · 项目实验</span><span>质量平台 · 检验缺陷</span><span>治理中心 · 可信数据</span><em><i></i>数据流在线</em></section>

 <div class="role-kpis"><article v-for="card in current.cards" :key="card.label" class="surface role-card" :class="card.tone" @click="drill(card.route)"><header><span>{{card.label}}</span><b>↗</b></header><strong>{{card.value}}</strong><p>{{card.hint}}</p><footer>{{card.source}}<span>点击下钻</span></footer></article></div>

 <section v-if="enabled.trend||enabled.status" class="visual-grid">
  <article v-if="enabled.trend" class="surface trend-panel"><header class="panel-head"><div><small>ROLE TREND / 近 8 周</small><h3>{{current.trendTitle}}</h3></div><div class="legend"><span class="a">{{current.seriesA}}</span><span class="b">{{current.seriesB}}</span></div></header><div class="paired-chart"><div v-for="(value,index) in current.trend" :key="index" class="pair"><div><i class="a" :style="{height:value+'%'}"></i><i class="b" :style="{height:current.compare[index]+'%'}"></i></div><span>W{{index+1}}</span></div></div><footer><span>▲ 当前周期保持上行</span><b>预测置信度 92.6%</b></footer></article>
  <article v-if="enabled.status" class="surface status-panel"><header class="panel-head"><div><small>STATUS DISTRIBUTION</small><h3>关键对象状态</h3></div><b class="live">LIVE</b></header><div class="status-body"><div class="status-ring" :style="{background:`conic-gradient(${current.status[0].color} 0 ${current.status[0].value}%,${current.status[1].color} ${current.status[0].value}% ${current.status[0].value+current.status[1].value}%,${current.status[2].color} 0)`}"><div><strong>{{current.status[0].value}}%</strong><span>核心状态</span></div></div><ul><li v-for="item in current.status" :key="item.label"><i :style="{background:item.color,boxShadow:`0 0 8px ${item.color}`}"/><span>{{item.label}}</span><b>{{item.value}}%</b></li></ul></div><button @click="drill(current.cards[0].route)">查看状态明细 →</button></article>
 </section>

 <section class="lower-grid">
  <article v-if="enabled.exceptions" class="surface exception-panel"><header class="panel-head"><div><small>EXCEPTION CENTER</small><h3>实时异常与风险</h3></div><el-tag type="danger" effect="dark">4 项待处理</el-tag></header><div class="exception-list"><button v-for="item in exceptions" :key="item.title" @click="drill(item.route)"><em :class="item.level==='紧急'?'critical':''">{{item.level}}</em><div><b>{{item.title}}</b><span>{{item.detail}}</span></div><p><strong>{{item.source}}</strong><time>{{item.time}}</time></p><i>›</i></button></div></article>
  <article v-if="enabled.sources" class="surface source-panel"><header class="panel-head"><div><small>DATA SOURCE TOPOLOGY</small><h3>数据来源与关联</h3></div><span class="flow-rate">1,842 msg/min</span></header><div class="source-topology"><div class="source-core"><b>统一数据底座</b><small>标准化 · 聚合 · 权限</small></div><button v-for="(node,index) in sourceNodes" :key="node.name" :class="['node',`node-${index+1}`,node.tone]" @click="drill(index<2?'/integration/overview':'/assets/overview')"><b>{{node.name}}</b><span>{{node.desc}}</span><em>{{node.state}}</em></button></div><p class="source-note">MES 提供生产执行，IoT 提供实时状态，平台汇聚研发、质量与治理数据。</p></article>
 </section>

 <section v-if="enabled.platform" class="surface platform-real"><header class="panel-head"><div><small>EXISTING PLATFORM CAPABILITIES</small><h3>现有平台真实运行数据</h3><p>此区域继续使用现有后端接口，未改变原有功能。</p></div><el-button v-if="auth.can('dataset:export')" :loading="exporting" @click="exportReport">导出决策报表</el-button></header><div class="platform-grid"><button v-for="item in platformCards" :key="item[0]" @click="drill(String(item[2]))"><span>{{item[0]}}</span><b>{{Number(item[1]).toLocaleString()}}</b></button><div><span>数据发布率</span><b>{{Number(report.kpis?.publicationRate||0).toFixed(1)}}%</b></div><div><span>设备在线率</span><b>{{Number(report.kpis?.onlineRate||0).toFixed(1)}}%</b></div></div></section>

 <el-drawer v-model="configVisible" title="角色驾驶舱组件配置" size="430"><div class="config-drawer"><p>配置仅保存在当前前端会话，用于演示不同角色的组件组合。</p><label v-for="(value,key) in enabled" :key="key"><span>{{({trend:'趋势图',status:'状态图',exceptions:'异常列表',sources:'数据来源拓扑',platform:'现有平台指标'} as any)[key]}}</span><el-switch v-model="enabled[key]"/></label></div></el-drawer>
</div></template>

